import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.BM5YPQmL.js";const i="/docs/screenshots/diff.png",p=JSON.parse('{"title":"Diff view","description":"","frontmatter":{},"headers":[],"relativePath":"guide/diff.md","filePath":"guide/diff.md","lastUpdated":1793464709000}'),s={name:"guide/diff.md"};function r(n,e,h,c,l,f){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="diff-view" tabindex="-1">Diff view <a class="header-anchor" href="#diff-view" aria-label="Permalink to &quot;Diff view&quot;">​</a></h1><p>The diff view compares two JSON documents and shows what was added, removed or changed. Switch to it using the <strong>diff</strong> tab in the header (route <code>/diff</code>).</p><p><img src="'+i+'" alt="Diff view"></p><p>The left editor holds the <strong>original</strong> document and the right editor holds the document to <strong>compare with</strong>. Both editors are resizable, support search, clipboard paste, file upload and clearing, just like the editor on the home view. The original document is the same working JSON used by the home, table and shape views.</p><h2 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h2><p>The summary shows how many differences were found:</p><table tabindex="0"><thead><tr><th>Statistic</th><th>Meaning</th></tr></thead><tbody><tr><td>Added</td><td>Values that exist only in the compared document</td></tr><tr><td>Removed</td><td>Values that exist only in the original document</td></tr><tr><td>Changed</td><td>Values that exist in both documents but are different</td></tr><tr><td>Differences</td><td>Total number of added, removed and changed entries</td></tr></tbody></table><p>Each difference lists its <strong>path</strong>, <strong>status</strong>, and the <strong>before</strong> and <strong>after</strong> values. A missing side is shown as <code>—</code>.</p><p>When both documents are identical, the view shows <strong>No differences. Both documents are identical.</strong></p><h2 id="paths" tabindex="-1">Paths <a class="header-anchor" href="#paths" aria-label="Permalink to &quot;Paths&quot;">​</a></h2><p>Paths use a JSONPath-like notation:</p><ul><li><code>$</code> is the root document.</li><li>Object properties are joined with a dot: <code>$.user.name</code>.</li><li>Array elements use their index: <code>$.users[0].name</code>.</li></ul><p>Arrays are compared by index. For example, when the item at index <code>1</code> changes, the difference is reported at <code>$.items[1]</code>; extra items are reported as added and missing items as removed.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>If either document is not valid JSON, the view reports <code>invalid json</code> instead of the differences. Paste valid JSON in both editors to compare them.</p>',15)])])}const u=t(s,[["render",r]]);export{p as __pageData,u as default};
